			}),
		);
	});

	it('reports a degraded upstream without throwing', async () => {
		const fetcher = vi
			.fn<typeof fetch>()
			.mockResolvedValue(new Response('unavailable', { status: 503 }));

		await expect(
			getApiHealth({ environment: { API_URL: 'https://private-api.vercel.sh' }, fetcher }),
		).resolves.toEqual(err({ code: 'UPSTREAM_FAILURE', message: 'The API health check failed.' }));
	});

	it('reports an unreachable upstream without throwing', async () => {
		const fetcher = vi.fn<typeof fetch>().mockRejectedValue(new Error('connection refused'));

