/** @description Parses the private API service binding injected by Vercel Services. */

import { EnvValidationError, defineEnv, parseEnv, urlValue } from '@tenets/env';
import type { EnvSource } from '@tenets/env';
import { err, ok } from '@tenets/result';
import type { Result } from '@tenets/result';

/** @description Validated server-only view of the API service binding. */
export interface ApiServiceEnvironment {
	readonly apiUrl: URL;
}

/** @description Recoverable reasons the binding cannot be used. */
export interface ApiServiceEnvironmentError {
	readonly code: 'MISSING_API_URL' | 'INVALID_API_URL';
	readonly message: string;
}

const opsEnvironment = defineEnv({
	name: 'ops',
	server: { API_URL: urlValue },
});

/** @description Parses a service-binding environment source without exposing raw process state downstream. */
export function parseApiServiceEnvironment(
	source: EnvSource,
): Result<ApiServiceEnvironment, ApiServiceEnvironmentError> {
	try {
		const env = parseEnv(opsEnvironment, source);
		return ok({ apiUrl: new URL(env.API_URL) });
	} catch (error) {
		// Only validation failures are recoverable; a broken definition is a
		// programmer error and must surface, not degrade into a health warning.
		if (!(error instanceof EnvValidationError)) {
			throw error;
		}
		const isMissing = error.issues.some(
			(issue) => issue.code === 'invalid_type' && issue.input === undefined,
		);
		return err(
			isMissing
				? {
						code: 'MISSING_API_URL',
						message: 'API_URL is required. Run through Vercel Services or configure it locally.',
					}
				: { code: 'INVALID_API_URL', message: 'API_URL must be an absolute URL.' },
		);
	}
}
